INSERT INTO pizzas(nome_della_pizza,pizza_description,price,photo_url)VALUES('Rò','Variante della classica Marinara con pomodoro San Marzano, aglio fresco, origano e ingredienti speciali della casa dal gusto intenso e tradizionale.',7.50,'https://example.com/images/ro.jpg'),('Re','Pizza Regina con pomodoro, mozzarella fiordilatte, prosciutto cotto di alta qualità e basilico fresco dal gusto equilibrato e delicato.',8.50,'https://example.com/images/re.jpg'),('Poli','Pizza con polpette artigianali, salsa di pomodoro, mozzarella filante e parmigiano reggiano, ispirata alla cucina tradizionale italiana.',9.00,'https://example.com/images/poli.jpg'),('Oro','Pizza ispirata ai sapori di Napoli con pomodoro San Marzano, mozzarella premium, olio extravergine di oliva e ingredienti selezionati.',10.00,'https://example.com/images/oro.jpg'),('Foc','Focaccia semplice con olio extravergine di oliva, rosmarino fresco e sale marino croccante cotta nel forno a legna tradizionale.',5.50,'https://example.com/images/foc.jpg'),('Scl','Pizza Siciliana con pomodoro, mozzarella, acciughe, capperi, olive nere e origano dal gusto mediterraneo deciso e autentico.',9.50,'https://example.com/images/scl.jpg'),('Margherita','Pizza classica napoletana con pomodoro San Marzano, mozzarella fiordilatte fresca e basilico profumato cotta nel forno a legna.',7.00,'https://example.com/images/margherita.jpg')('Marinara','Pizza tradizionale con pomodoro San Marzano, aglio fresco, origano e olio extravergine di oliva senza mozzarella.',6.00,'https://example.com/images/marinara.jpg'),('Diavola','Pizza con pomodoro, mozzarella filante e salame piccante italiano dal gusto forte e leggermente speziato.',8.50,'https://example.com/images/diavola.jpg'),('Caprese','Pizza ispirata alla caprese con pomodoro fresco, mozzarella di bufala, basilico e olio extravergine di oliva.',9.00,'https://example.com/images/caprese.jpg'),('Bufala Gourmet','Pizza gourmet con Mozzarella di Bufala Campana DOP, Pomodorini del Piennolo, b